    overview: ["New York is a collection of cities inside one metropolitan system: museum Manhattan, neighborhood Brooklyn, theater Midtown, historic Lower Manhattan, and food-led districts beyond the postcard route. Its value is variety, but that variety makes prioritization essential.", "Choose New York when you want maximum urban choice and are willing to spend for convenience. A good trip groups neighborhoods, museums, meals, and evenings without burning time in transit."],
    thingSections: [{ title: "Classic Manhattan", items: [{ name: "Central Park and the Met", description: "Pair green space with one serious museum block for a day with both scale and recovery time." }, { name: "Lower Manhattan and the harbor", description: "Use the Statue of Liberty, waterfront, and financial district as one route." }, { name: "Midtown and Broadway", description: "Choose Times Square as the orientation point, then make the show the real priority." }] }, { title: "Neighborhood New York", items: [{ name: "Brooklyn Bridge and DUMBO", description: "Cross the bridge when skyline and Brooklyn food are more appealing than another Midtown stop." }, { name: "Greenwich Village and SoHo", description: "Choose them for walking, food, shopping, and a less monumental view of Manhattan." }, { name: "Queens or Brooklyn food routes", description: "Use a borough day when local texture matters more than another famous building." }] }],
    foods: [{ name: "Pizza and bagels", description: "Practical city staples for fitting good food around a packed route." }, { name: "Immigrant neighborhood food", description: "Queens, Chinatown, Koreatown, and other districts show why New York is a food destination." }, { name: "Deli and bakery stops", description: "Casual stops help control cost and sustain long walking days." }],
    neighborhoods: [{ name: "Midtown", bestFor: "First-time central logistics and Broadway", tradeoff: "Busy, commercial, and expensive.", description: "Convenient for major landmarks and shows, but less neighborhood-like." }, { name: "SoHo / Greenwich Village", bestFor: "Shopping, food, and walkable evenings", tradeoff: "High hotel prices and limited quiet.", description: "A strong base for Manhattan street life outside Midtown." }, { name: "Upper West Side", bestFor: "Museums, Central Park, and calmer evenings", tradeoff: "Farther from Lower Manhattan nightlife.", description: "Useful for families and museum travelers." }, { name: "Brooklyn Heights / DUMBO", bestFor: "Skyline views and Brooklyn access", tradeoff: "Less efficient for daily Midtown routes.", description: "Choose it when bridge, waterfront, and Brooklyn food are central." }],
    gettingAround: [{ name: "Subway and walking", description: "The subway is the backbone, but stations and transfers add time; plan neighborhood clusters." }, { name: "Airport choice", description: "JFK, Newark, and LaGuardia create different arrival routes, so hotel location matters immediately." }, { name: "Borough scale", description: "Do not combine distant boroughs with multiple Manhattan priorities unless the route itself is the day's focus." }],
    bestTime: [{ name: "Spring and autumn", description: "Comfortable walking weather supports parks, neighborhoods, and outdoor routes." }, { name: "Summer tradeoff", description: "Long days and events help, but heat, crowds, and hotel demand raise the total." }, { name: "Winter", description: "Museums, shows, food, and indoor attractions remain strong, but outdoor routes are less flexible." }],
